(function() {
    'use strict';

    var ROUNDS = [
        {
            number: 1,
            title: 'Diagnose and Set Hybrid Policy',
            briefing: '<strong>Month 1-3:</strong> You are the newly appointed VP of People & Culture at Solaris Software, a \u20ac550M B2B SaaS company headquartered in Barcelona with 3,800 employees across 12 countries.<br><br>The CEO demands a return-to-office mandate to revitalize innovation. Your VP Engineering advocates remote-first. Enterprise sales wants in-person presence. Your talent analytics show cultural fragmentation between HQ and remote employees.<br><br><strong>Baseline Metrics:</strong> Engagement 78/100, Innovation 72/100, Turnover 12%, Culture Coherence 68/100.<br><br>Your first decision: what hybrid work policy will Solaris adopt for the next 18 months?',
            controlsId: 'round1Controls'
        },
        {
            number: 2,
            title: 'Design Cultural Infrastructure',
            briefing: '<strong>Month 4-7:</strong> Your hybrid policy is now in effect. It is time to design the cultural infrastructure\u2014rituals, spaces, leadership practices, and virtual artifacts\u2014that will maintain organizational coherence across 12 countries.<br><br>You have a dedicated cultural investment budget of <strong>\u20ac800,000</strong> for the 18-month cycle. Allocate wisely across retreats, technology, office redesign, leadership development, and mentorship.<br><br>Consider: Will you invest in in-person rituals that maximize presence but may exclude caregivers? Or async culture that preserves inclusion but requires discipline?',
            controlsId: 'round2Controls'
        },
        {
            number: 3,
            title: 'Navigate Innovation Crisis',
            briefing: '<strong>Month 8-11:</strong> <strong style="color:#c0392b;">\u26a0 CRISIS:</strong> Solaris launched a new product line built over 18 months, but it received lukewarm customer reception and technical quality issues. Post-launch analysis reveals insufficient cross-functional ideation\u2014engineering and product teams worked in isolation.<br><br>The CEO attributes the problem to isolation from the hybrid policy. Pressure mounts to mandate more office days. The VP Engineering disagrees, citing alternative root causes (weak product strategy, technical debt).<br><br>How will you respond? Increase office time, defend the current model, or redesign collaboration architecture?',
            controlsId: 'round3Controls'
        },
        {
            number: 4,
            title: 'Address Manager Perception Gap',
            briefing: '<strong>Month 12-15:</strong> A systematic manager survey reveals a crisis of perception: 70% of managers report high trust in remote employees, yet 68% of employees believe office presence is correlated with promotion and advancement.<br><br>Exit interviews show departing employees frequently cite "lack of advancement opportunity" and "felt overlooked despite strong performance." Promotion data confirms that visible, office-based employees advance faster.<br><br>This perception gap undermines culture authenticity. Will you redesign performance evaluation, increase career transparency, invest in training, or overhaul the promotion process?',
            controlsId: 'round4Controls'
        },
        {
            number: 5,
            title: 'Build Sustainable Architecture',
            briefing: '<strong>Month 16-18:</strong> You now have 15 months of decisions behind you. Your task is to design a sustainable culture model that integrates all prior decisions into a coherent architecture that can adapt as context changes.<br><br>Finalize your hybrid policy direction, choose a measurement system to track culture health, and establish a governance model for ongoing culture decisions.<br><br>The goal is coherence: policy, management practices, cultural artifacts, measurement, and leadership should all align around a clear culture strategy. What will define Solaris for the next era?',
            controlsId: 'round5Controls'
        }
    ];

    class CultureHybridAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CultureHybrid: Designing Organizational Culture';
            this.version = '1.1.0';
            this._dsSnaps = [];
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: 78,
                    innovation: 72,
                    turnover: 12,
                    coherence: 68,
                    budgetTotal: 800000,
                    budgetSpent: 0,
                    officeDays: 2,
                    engagementHistory: [],
                    innovationHistory: [],
                    turnoverHistory: [],
                    coherenceHistory: [],
                    compositeHistory: [],
                    eventLog: '',
                    coherenceStreak: 0
                };
                this._dsSnaps = [JSON.parse(JSON.stringify(state.domainState))];
            } else {
                var h = (state.history || []).length;
                if (this._dsSnaps.length > h + 1 && this._dsSnaps[h]) {
                    var snap = JSON.parse(JSON.stringify(this._dsSnaps[h]));
                    var ds0 = state.domainState;
                    for (var k in ds0) { if (!(k in snap)) delete ds0[k]; }
                    for (var k2 in snap) { ds0[k2] = snap[k2]; }
                    this._dsSnaps = this._dsSnaps.slice(0, h + 1);
                }
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    officeDays: 2,
                    transparency: 2,
                    geoFlexibility: 2,
                    enforcement: 2
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var el = document.getElementById(this.ROUNDS[i].controlsId);
                if (el) el.style.display = (i === idx) ? 'block' : 'none';
            }

            var slider = document.getElementById('officeDaysInput');
            var sliderVal = document.getElementById('officeDaysValue');
            if (slider && sliderVal) {
                slider.oninput = function() { sliderVal.textContent = slider.value; };
            }

            this._setupBudgetListeners();
        }

        _setupBudgetListeners() {
            var ids = ['retreatBudgetInput', 'techBudgetInput', 'officeBudgetInput', 'leadershipBudgetInput', 'mentorshipBudgetInput'];
            var totalEl = document.getElementById('budgetTotalDisplay');
            if (!totalEl) return;

            function updateTotal() {
                var sum = 0;
                for (var i = 0; i < ids.length; i++) {
                    var inp = document.getElementById(ids[i]);
                    if (inp) sum += parseInt(inp.value) || 0;
                }
                totalEl.textContent = '\u20ac' + sum.toLocaleString();
            }

            for (var i = 0; i < ids.length; i++) {
                var inp = document.getElementById(ids[i]);
                if (inp) inp.oninput = updateTotal;
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;
            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                var slider = document.getElementById('officeDaysInput');
                if (slider) decisions.officeDays = parseInt(slider.value);
                var trans = document.getElementById('transparencyInput');
                if (trans) decisions.transparency = parseInt(trans.value);
                var geo = document.getElementById('geoFlexInput');
                if (geo) decisions.geoFlexibility = parseInt(geo.value);
                var enf = document.getElementById('enforcementInput');
                if (enf) decisions.enforcement = parseInt(enf.value);
            } else if (period === 2) {
                decisions.retreatBudget = parseInt(document.getElementById('retreatBudgetInput').value) || 0;
                decisions.techBudget = parseInt(document.getElementById('techBudgetInput').value) || 0;
                decisions.officeBudget = parseInt(document.getElementById('officeBudgetInput').value) || 0;
                decisions.leadershipBudget = parseInt(document.getElementById('leadershipBudgetInput').value) || 0;
                decisions.mentorshipBudget = parseInt(document.getElementById('mentorshipBudgetInput').value) || 0;
                var totalBudget = decisions.retreatBudget + decisions.techBudget + decisions.officeBudget + decisions.leadershipBudget + decisions.mentorshipBudget;
                if (totalBudget > 800000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                    return false;
                }
                if (totalBudget < 100000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_low_warning'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var cr = document.getElementById('crisisResponseInput');
                if (cr) decisions.crisisResponse = parseInt(cr.value);
                var ca = document.getElementById('collabArchInput');
                if (ca) decisions.collabArchitecture = parseInt(ca.value);
                var ma = document.getElementById('mgrAccountInput');
                if (ma) decisions.managerAccountability = parseInt(ma.value);
            } else if (period === 4) {
                var ev = document.getElementById('evalRedesignInput');
                if (ev) decisions.evalRedesign = parseInt(ev.value);
                var ct = document.getElementById('careerTransInput');
                if (ct) decisions.careerTransparency = parseInt(ct.value);
                var tr = document.getElementById('trainingInput');
                if (tr) decisions.trainingDepth = parseInt(tr.value);
                var pr = document.getElementById('promotionInput');
                if (pr) decisions.promotionProcess = parseInt(pr.value);
            } else if (period === 5) {
                var pf = document.getElementById('policyFinalInput');
                if (pf) decisions.policyFinal = parseInt(pf.value);
                var ms = document.getElementById('measurementInput');
                if (ms) decisions.measurementSystem = parseInt(ms.value);
                var gv = document.getElementById('governanceInput');
                if (gv) decisions.governance = parseInt(gv.value);
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var deltaE = 0;
            var deltaI = 0;
            var deltaT = 0;
            var deltaC = 0;
            var eventMsg = '';

            if (period === 1) {
                ds.officeDays = d.officeDays;
                if (d.officeDays <= 1) {
                    deltaE += 3;
                    deltaI -= 4;
                    deltaT -= 1;
                    deltaC -= 3;
                    eventMsg = '<strong>Talent Advisory Board Alert:</strong> Senior employees (10-15 year tenure) express concern that a fully remote policy risks losing institutional knowledge and mentorship culture. "We worry Solaris will become just a group of disconnected engineers."';
                } else if (d.officeDays >= 4) {
                    deltaE -= 4;
                    deltaI += 3;
                    deltaT += 3;
                    deltaC += 2;
                    eventMsg = '<strong>Competitor Aggressive Recruiting:</strong> Rival company Workiva announces a fully remote policy and launches targeted recruitment at Solaris, emphasizing flexibility. They are targeting your high-performing engineers aged 25-32.';
                } else {
                    deltaE += 1;
                    deltaI += 1;
                    deltaT -= 0.5;
                    deltaC -= 2;
                    eventMsg = '<strong>Manager Clarity Crisis:</strong> An interim survey reveals 60% of managers have created informal variations on the policy within their teams. Some do 2 days, others 1, some are still mostly remote. Policy clarity is lower than assumed.';
                }

                if (d.transparency === 3) {
                    deltaE += 3;
                    deltaC += 3;
                } else if (d.transparency === 2) {
                    deltaE += 1;
                    deltaC += 1;
                } else {
                    deltaE -= 2;
                    deltaC -= 2;
                }

                if (d.geoFlexibility === 2) {
                    deltaE += 1;
                    deltaC -= 1;
                }

                if (d.enforcement === 2) {
                    deltaC += 2;
                    deltaE -= 1;
                } else {
                    deltaC -= 1;
                    deltaE += 1;
                }
            } else if (period === 2) {
                var totalSpent = d.retreatBudget + d.techBudget + d.officeBudget + d.leadershipBudget + d.mentorshipBudget;
                ds.budgetSpent = totalSpent;

                if (d.retreatBudget >= 200000) {
                    deltaC += 3;
                    deltaE += 2;
                    eventMsg = '<strong>Equity Concern:</strong> Employee resource groups surface that annual retreats create disproportionate burden on employees with caregiving responsibilities, visa constraints, or lower socioeconomic status. In-person-heavy culture inadvertently creates a two-tier culture.';
                    deltaE -= 3;
                    deltaC -= 2;
                } else if (d.techBudget >= 150000) {
                    deltaI += 2;
                    deltaE += 1;
                    eventMsg = '<strong>Culture Ambassador Burnout:</strong> The culture ambassadors program shows burnout signals. Volunteers spend 3-4 hours per week outside regular roles. Retention among ambassadors is declining.';
                    deltaE -= 1;
                } else {
                    deltaE += 2;
                    deltaC += 2;
                    eventMsg = '<strong>Informal Culture Thriving:</strong> Organic culture initiatives are emerging spontaneously: local team coffee groups, self-organized Slack communities, and informal mentorship. Culture emerges as much as it is designed!';
                }

                if (d.officeBudget >= 200000) {
                    deltaI += 2;
                    deltaC += 1;
                }
                if (d.leadershipBudget >= 100000) {
                    deltaC += 2;
                    deltaE += 1;
                }
                if (d.mentorshipBudget >= 60000) {
                    deltaE += 1;
                    deltaT -= 1;
                }
            } else if (period === 3) {
                if (d.crisisResponse === 1) {
                    deltaI += 3;
                    deltaE -= 4;
                    deltaT += 3;
                    deltaC += 1;
                    eventMsg = '<strong>Compensation Backlash:</strong> Employees with family caregiving responsibilities (disproportionately women) face new pressure to increase office presence. Several key female engineers are reconsidering their tenure. High performers who chose Solaris for flexibility feel misled.';
                } else if (d.crisisResponse === 2) {
                    deltaI -= 2;
                    deltaE += 1;
                    deltaC -= 1;
                    eventMsg = '<strong>Customer Advisory Board Feedback:</strong> Enterprise accounts perceive innovation is slowing compared to competitors. Customer satisfaction is vulnerable. Sales team feels pressure to defend the product roadmap.';
                } else {
                    deltaI += 4;
                    deltaE += 3;
                    deltaT -= 1;
                    deltaC += 2;
                    eventMsg = '<strong>Unexpected Success:</strong> Within 60 days of new collaboration architecture, the product team launches an innovation sprint generating three novel feature concepts with strong customer feedback. Hybrid work can support innovation with the right architecture!';
                }

                if (d.collabArchitecture === 3) {
                    deltaI += 2;
                    deltaE += 1;
                } else if (d.collabArchitecture === 2) {
                    deltaI += 1;
                } else if (d.collabArchitecture === 4) {
                    deltaI += 1;
                    deltaE -= 1;
                }

                if (d.managerAccountability === 1) {
                    deltaC += 2;
                    deltaI += 1;
                } else if (d.managerAccountability === 3) {
                    deltaC += 1;
                    deltaE += 1;
                }
            } else if (period === 4) {
                var systemicScore = 0;
                if (d.evalRedesign === 1) systemicScore += 2;
                if (d.evalRedesign === 2) systemicScore += 1;
                if (d.evalRedesign === 3) systemicScore += 1;
                if (d.careerTransparency === 3) systemicScore += 2;
                if (d.careerTransparency === 2) systemicScore += 1;
                if (d.careerTransparency === 1) systemicScore += 1;
                if (d.trainingDepth === 1) systemicScore += 2;
                if (d.trainingDepth === 3) systemicScore += 1;
                if (d.promotionProcess === 1) systemicScore += 3;

                if (systemicScore >= 7) {
                    deltaE += 4;
                    deltaC += 3;
                    deltaT -= 2;
                    eventMsg = '<strong>Culture Shift Signals:</strong> Engagement survey shows perception of fairness increased from 52% to 67%. Promotion data now shows remote employees advance at equitable rates. Systemic change works! Mid-career talent retention is improving.';
                } else if (systemicScore >= 4) {
                    deltaE += 1;
                    deltaC += 1;
                    eventMsg = '<strong>Partial Progress:</strong> Manager awareness of bias has increased, but promotion patterns are only beginning to shift. Employees appreciate the effort but remain skeptical. More structural change is needed to build trust.';
                } else {
                    deltaE -= 3;
                    deltaC -= 2;
                    deltaT += 1;
                    eventMsg = '<strong>Credibility Crisis:</strong> Despite published career criteria and transparency messaging, advancement patterns have not changed. Employees experience the communication as gaslighting: "They say there is no office bias, but all promotions still go to people in the office."';
                }
            } else if (period === 5) {
                var totalCoherence = 0;

                var engTrend = ds.engagementHistory.length >= 2 ? ds.engagementHistory[ds.engagementHistory.length - 1] - ds.engagementHistory[0] : 0;
                var cohTrend = ds.coherenceHistory.length >= 2 ? ds.coherenceHistory[ds.coherenceHistory.length - 1] - ds.coherenceHistory[0] : 0;
                var innTrend = ds.innovationHistory.length >= 2 ? ds.innovationHistory[ds.innovationHistory.length - 1] - ds.innovationHistory[0] : 0;

                if (engTrend > 3 && cohTrend > 3 && innTrend > 0) totalCoherence += 3;
                else if (engTrend > 0 || cohTrend > 0) totalCoherence += 1;

                if (d.policyFinal === 3) {
                    deltaE += 2;
                    deltaC += 1;
                    totalCoherence += 1;
                } else if (d.policyFinal === 1) {
                    deltaC += 2;
                    totalCoherence += 1;
                } else {
                    deltaE += 1;
                    deltaI += 1;
                }

                if (d.measurementSystem === 4) {
                    deltaC += 3;
                    deltaE += 1;
                    totalCoherence += 2;
                } else if (d.measurementSystem === 3) {
                    deltaC += 2;
                    totalCoherence += 1;
                } else if (d.measurementSystem === 2) {
                    deltaC += 1;
                    deltaE += 1;
                }

                if (d.governance === 2) {
                    deltaC += 2;
                    deltaE += 2;
                    totalCoherence += 1;
                } else if (d.governance === 3) {
                    deltaC += 1;
                    deltaE += 3;
                } else {
                    deltaC += 1;
                    deltaI += 1;
                }

                if (totalCoherence >= 6) {
                    deltaE += 4;
                    deltaT -= 2;
                    deltaC += 3;
                    eventMsg = '<strong>Culture as Competitive Advantage:</strong> Solaris culture becomes a topic in industry conversations. Exit interviews from departing competitor employees mention Solaris as a factor in their interest. Intentional hybrid culture design has become a recruiting advantage!';
                } else if (totalCoherence >= 3) {
                    deltaE += 1;
                    deltaC += 1;
                    eventMsg = '<strong>Culture Stabilizing:</strong> Solaris has achieved functional hybrid culture with acceptable engagement and innovation. Some areas need further attention, but the trajectory is positive. Strategy coherence is building.';
                } else {
                    deltaC -= 2;
                    eventMsg = '<strong>Culture Fragmentation:</strong> Different regions and teams have customized their culture adaptations, resulting in a portfolio of subcultures rather than a unified organization. Some thrive locally, but cross-team collaboration remains weak.';
                }
            }

            var newE = Math.max(0, Math.min(100, ds.engagement + deltaE));
            var newI = Math.max(0, Math.min(100, ds.innovation + deltaI));
            var newT = Math.max(2, Math.min(25, ds.turnover + deltaT));
            var newC = Math.max(0, Math.min(100, ds.coherence + deltaC));

            ds.engagement = Math.round(newE * 10) / 10;
            ds.innovation = Math.round(newI * 10) / 10;
            ds.turnover = Math.round(newT * 10) / 10;
            ds.coherence = Math.round(newC * 10) / 10;

            var composite = Math.round(((ds.engagement * 0.30) + (ds.innovation * 0.25) + ((100 - ds.turnover * 12.5) * 0.25) + (ds.coherence * 0.20)) * 10) / 10;
            composite = Math.max(0, Math.min(100, composite));

            ds.engagementHistory.push(ds.engagement);
            ds.innovationHistory.push(ds.innovation);
            ds.turnoverHistory.push(ds.turnover);
            ds.coherenceHistory.push(ds.coherence);
            ds.compositeHistory.push(composite);
            ds.eventLog = eventMsg;

            this._dsSnaps[period] = JSON.parse(JSON.stringify(ds));

            var evtPanel = document.getElementById('eventPanel');
            var evtText = document.getElementById('eventText');
            if (evtPanel && evtText && eventMsg) {
                evtPanel.style.display = 'block';
                evtText.innerHTML = eventMsg;
            }

            if (period < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            var roundTitle = ROUNDS[Math.min(period - 1, ROUNDS.length - 1)].title;

            return {
                period: period,
                roundTitle: roundTitle,
                engagement: ds.engagement,
                innovation: ds.innovation,
                turnover: ds.turnover,
                coherence: ds.coherence,
                composite: composite,
                event: eventMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('engagementDisplay', 'domainState.engagement', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('innovationDisplay', 'domainState.innovation', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('turnoverDisplay', 'domainState.turnover', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('coherenceDisplay', 'domainState.coherence', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('budgetDisplay', 'domainState.budgetSpent', function(v) { return '\u20ac' + (800000 - v).toLocaleString(); });
        }

        getChartConfig() {
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Engagement',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Innovation',
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Coherence',
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.1)',
                                borderWidth: 3,
