        getChartData(state) {
            var labels = state.domainState.engagementHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.engagementHistory },
                        { data: state.domainState.innovationHistory },
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.compositeHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var composite = last.results ? last.results.composite : 0;
            var performance = 'Critical';
            if (composite >= 85) performance = 'Excellent';
            else if (composite >= 75) performance = 'Good';
            else if (composite >= 65) performance = 'Acceptable';
            else if (composite >= 55) performance = 'Concerning';

            var avgComposite = history.reduce(function(s, r) { return s + (r.results ? r.results.composite : 0); }, 0) / history.length;

            var insights = [];
            if (last.results) {
                if (last.results.engagement >= 85) insights.push('Strong employee engagement signals a healthy, trust-based culture.');
                if (last.results.engagement < 70) insights.push('Engagement remains below target. Consider deeper investment in employee voice and transparency.');
                if (last.results.innovation >= 80) insights.push('Innovation output is strong. Cross-functional collaboration architecture is working.');
                if (last.results.innovation < 65) insights.push('Innovation needs attention. Review collaboration structures and serendipity opportunities.');
                if (last.results.turnover <= 9) insights.push('Turnover is well-managed. Retention strategies are effective.');
                if (last.results.turnover > 12) insights.push('Turnover remains elevated. Review fairness of promotion processes and flexibility policies.');
                if (last.results.coherence >= 80) insights.push('Culture coherence is strong. Shared values are experienced consistently across geographies.');
                if (last.results.coherence < 65) insights.push('Culture fragmentation is a concern. Invest in unifying artifacts and governance.');
            }
            if (insights.length === 0) {
                insights.push('Solaris has navigated the hybrid work challenge with mixed results. Strategic coherence matters.');
            }

            return {
                finalComposite: composite,
                averageComposite: Math.round(avgComposite * 10) / 10,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.composite < 60) return window.mySimulation.t('hint_low_composite');
            if (results.turnover > 14) return window.mySimulation.t('hint_high_turnover');
            if (results.innovation < 65) return window.mySimulation.t('hint_low_innovation');
            if (results.coherence < 60) return window.mySimulation.t('hint_low_coherence');
            if (results.composite >= 80) return window.mySimulation.t('hint_strong');
            return null;
        }

